// The fixture (testdata/releaseverify, shipped with the public Core) is generated by tests/tools/gen_releaseverify_fixture.py; its
// expected/*.stdout and *.rc are the Python verifier's, backend word rewritten.
var fixtureDir = filepath.Join("testdata", "releaseverify")

var binary string

func TestMain(m *testing.M) {
	dir, err := os.MkdirTemp("", "pail_verify-test-")
	if err != nil {
		panic(err)
	}
	binary = filepath.Join(dir, "pail_verify")
	goTool, err := exec.LookPath("go")
	if err != nil {
		goTool = filepath.Join(runtime.GOROOT(), "bin", "go")
	}
	build := exec.Command(goTool, "build", "-o", binary, ".")
	build.Stderr = os.Stderr
	if err := build.Run(); err != nil {
		os.RemoveAll(dir)
		panic("go build: " + err.Error())
	}
	rc := m.Run()
	os.RemoveAll(dir)
	os.Exit(rc)
}

type fixtureCase struct {
	Name            string   `json:"name"`
	Zip             string   `json:"zip"`
	Manifest        string   `json:"manifest"`
	ExpectedRelease string   `json:"expected_release"`
	PublicKey       string   `json:"public_key"`
	Args            []string `json:"args"`
}

type fixture struct {
	Artifact           string        `json:"artifact"`
	ReleaseID          string        `json:"release_id"`
	TestKeyFingerprint string        `json:"test_key_fingerprint"`
	Cases              []fixtureCase `json:"cases"`
}

func loadFixture(t *testing.T) (string, fixture) {
	t.Helper()
	root, err := filepath.Abs(fixtureDir)
	if err != nil {
		t.Fatal(err)
	}
	data, err := os.ReadFile(filepath.Join(root, "cases.json"))
	if err != nil {
		t.Fatalf("fixture missing (run tests/tools/gen_releaseverify_fixture.py): %v", err)
	}
	var f fixture
	if err := json.Unmarshal(data, &f); err != nil {
		t.Fatal(err)
	}
	return root, f
}

func runBinary(t *testing.T, env []string, args ...string) (string, string, int) {
	t.Helper()
	cmd := exec.Command(binary, args...)
	cmd.Env = append(os.Environ(), env...)
	var out, errb strings.Builder
	cmd.Stdout, cmd.Stderr = &out, &errb
	err := cmd.Run()
	rc := 0
	var exitErr *exec.ExitError
	if errors.As(err, &exitErr) {
		rc = exitErr.ExitCode()
	} else if err != nil {
		t.Fatal(err)
	}
	return out.String(), errb.String(), rc
}

func TestFixtureCasesMatchPythonVerifier(t *testing.T) {
	root, f := loadFixture(t)
	if len(f.Cases) < 20 {
		t.Fatalf("only %d cases", len(f.Cases))
	}
	// The generator writes the ignored entries of tree-dsstore-ignored, but .DS_Store and __pycache__/ are gitignored
	// (PAIL-v2/.gitignore), so a fresh checkout or the Core snapshot lacks them; seed the same bytes so the case keeps
	// proving the ignore list rather than degenerating into a second tree-match.
	ignoredTree := filepath.Join(root, "tree-dsstore-ignored", "tree")
	for rel, data := range map[string][]byte{".DS_Store": {0, 0, 0, 1, 'B', 'u', 'd', '1'}, "pail-core/__pycache__/x.pyc": {0, 'p', 'y', 'c'}} {
		p := filepath.Join(ignoredTree, filepath.FromSlash(rel))
		if _, err := os.Stat(p); err == nil {
			continue
		}
		if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(p, data, 0o644); err != nil {
			t.Fatal(err)
		}
	}
	trees := 0
	for _, c := range f.Cases {
		t.Run(c.Name, func(t *testing.T) {
			wantOut, err := os.ReadFile(filepath.Join(root, "expected", c.Name+".stdout"))
			if err != nil {
				t.Fatal(err)
			}
			rcText, err := os.ReadFile(filepath.Join(root, "expected", c.Name+".rc"))
			if err != nil {
				t.Fatal(err)
			}
			wantRC, _ := strconv.Atoi(strings.TrimSpace(string(rcText)))
			args := []string{"--zip", filepath.Join(root, c.Zip), "--manifest", filepath.Join(root, c.Manifest),
				"--expected-release", c.ExpectedRelease, "--public-key", filepath.Join(root, c.PublicKey), "--no-receipt"}
			for i, a := range c.Args {
				// --tree-root is relative to the fixture root in cases.json (the Python verifier runs from there).
				if i > 0 && c.Args[i-1] == "--tree-root" {
					a = filepath.Join(root, a)
					trees++
				}
				args = append(args, a)
			}
			out, errOut, rc := runBinary(t, nil, args...)
			if out != string(wantOut) || rc != wantRC {
				t.Errorf("rc %d want %d\n got: %q\nwant: %q\nstderr: %s", rc, wantRC, out, wantOut, errOut)
			}
			if errOut != "" {
				t.Errorf("stderr not empty: %s", errOut)
			}
		})
	}
	if trees != 3 {
		t.Errorf("%d tree cases, want 3 (tree-match, tree-modified, tree-dsstore-ignored)", trees)
	}
	// Every case without a tree root says so; the tree cases print the three documented lines.
	for name, want := range map[string]string{
		"good":                 "TREE: not compared (no images.lock.json beside the tree root; run from the extracted pail-evaluation/ directory to compare)\n",
		"allow-unsigned":       "TREE: not compared (no images.lock.json beside the tree root; run from the extracted pail-evaluation/ directory to compare)\n",
		"tree-match":           "TREE: MATCHES manifest (7 files compared; images/ archives are verified by load)\n",
		"tree-dsstore-ignored": "TREE: MATCHES manifest (7 files compared; images/ archives are verified by load)\n",
		"tree-modified":        "TREE: MODIFIED — 1 changed, 1 missing, 1 extra: pail-core/README.md(changed), pail-core/extra.txt(extra), run.sh(missing)\n",
	} {
		data, err := os.ReadFile(filepath.Join(root, "expected", name+".stdout"))
		if err != nil {
			t.Fatal(err)
		}
		anchor := "PUBLISHER_KEY: NOT_COMPARED — signature self-consistency only; obtain the fingerprint independently and pass --expected-fingerprint\n"
		if name == "allow-unsigned" {
			anchor = "PUBLISHER_KEY: NOT_AUTHENTICATED — signature not verified\n"
		}
		if !strings.Contains(string(data), "\nVERIFIER: this is the bundled verifier (pail_verify)\n"+anchor+want) {
			t.Errorf("%s golden:\n%s", name, data)
		}
	}
	// A signature FAIL still reports the verifier (P42-L2) but never a tree; an archive FAIL (before the signature
	// step) prints neither.
	for _, name := range []string{"sig-missing", "wrong-key", "key-missing", "fingerprint-mismatch"} {
		data, _ := os.ReadFile(filepath.Join(root, "expected", name+".stdout"))
		if !strings.HasSuffix(string(data), "\nVERIFIER: this is the bundled verifier (pail_verify)\n") || strings.Contains(string(data), "TREE:") {
			t.Errorf("signature FAIL %s:\n%s", name, data)
		}
	}
	for _, name := range []string{"member-tampered", "identity-mismatch", "duplicate-manifest-key"} {
		data, _ := os.ReadFile(filepath.Join(root, "expected", name+".stdout"))
		if strings.Contains(string(data), "TREE:") || strings.Contains(string(data), "VERIFIER:") {
			t.Errorf("archive FAIL %s prints verifier/tree lines:\n%s", name, data)
		}
	}
}

func TestTreeRootFlags(t *testing.T) {
	root, f := loadFixture(t)
	good := filepath.Join(root, "good", f.Artifact)
	key := filepath.Join(root, "TEST-SIGNING-KEY.pub")
	base := []string{"--zip", good, "--manifest", good + ".manifest.json", "--expected-release", f.ReleaseID, "--public-key", key, "--no-receipt"}
	tree := filepath.Join(root, "tree-match", "tree")
	// --tree-root defaults to --bundle-root; the key is still looked up under --bundle-root.
	out, _, rc := runBinary(t, nil, append(base, "--bundle-root", tree)...)
	if rc != 0 || !strings.HasSuffix(out, "TREE: MATCHES manifest (7 files compared; images/ archives are verified by load)\n") {
		t.Errorf("bundle-root as tree root: rc %d\n%s", rc, out)
	}
	// --no-tree-check skips even when a tree is given; a root without images.lock.json (or with a symlinked one) is
	// not compared, with a path-free message.
	out, _, rc = runBinary(t, nil, append(base, "--tree-root", tree, "--no-tree-check")...)
	if rc != 0 || !strings.HasSuffix(out, "TREE: skipped (--no-tree-check)\n") {
		t.Errorf("no-tree-check: rc %d\n%s", rc, out)
	}
	notCompared := "TREE: not compared (no images.lock.json beside the tree root; run from the extracted pail-evaluation/ directory to compare)\n"
	out, _, rc = runBinary(t, nil, append(base, "--tree-root", filepath.Join(tree, "pail-core"))...)
	if rc != 0 || !strings.HasSuffix(out, notCompared) {
		t.Errorf("root without lock: rc %d\n%s", rc, out)
	}
	linked := t.TempDir()
	os.Symlink(filepath.Join(tree, "images.lock.json"), filepath.Join(linked, "images.lock.json"))
	out, _, rc = runBinary(t, nil, append(base, "--tree-root", linked)...)
	if rc != 0 || !strings.HasSuffix(out, notCompared) {
		t.Errorf("symlinked lock: rc %d\n%s", rc, out)
	}
	// A FIFO prints as (irregular) and counts as extra; the walk never turns into "not compared".
	fifoTree := t.TempDir()
	for _, rel := range []string{"images.lock.json", "run.sh", "native/BUILD.json", "pail-core/README.md", "pail-core/cloud/go.sum", "pail-core/docs/ßœ.md", "pail-core/docs/🤖.md"} {
		data, _ := os.ReadFile(filepath.Join(tree, filepath.FromSlash(rel)))
		os.MkdirAll(filepath.Dir(filepath.Join(fifoTree, rel)), 0o755)
		os.WriteFile(filepath.Join(fifoTree, rel), data, 0o644)
	}
	if err := syscall.Mkfifo(filepath.Join(fifoTree, "pail-core", "pipe"), 0o644); err != nil {
		t.Fatal(err)
	}
	out, _, rc = runBinary(t, nil, append(base, "--tree-root", fifoTree)...)
	if rc != 0 || !strings.HasSuffix(out, "TREE: MODIFIED — 0 changed, 0 missing, 1 extra: pail-core/pipe(irregular)\n") {
		t.Errorf("fifo: rc %d\n%s", rc, out)
	}
	if os.Geteuid() != 0 {
		os.Remove(filepath.Join(fifoTree, "pail-core", "pipe"))
		os.Chmod(filepath.Join(fifoTree, "run.sh"), 0)
		t.Cleanup(func() { os.Chmod(filepath.Join(fifoTree, "run.sh"), 0o644) })
		out, _, rc = runBinary(t, nil, append(base, "--tree-root", fifoTree)...)
		if rc != 0 || !strings.HasSuffix(out, "TREE: MODIFIED — 0 changed, 1 missing, 1 extra: run.sh(missing), run.sh(unreadable)\n") {
			t.Errorf("unreadable: rc %d\n%s", rc, out)
		}
	}
	// A receipt directory inside the delivery tree is refused (it would be an extra file of the next run).
	for _, dir := range []string{tree, filepath.Join(tree, "pail-core", "receipts")} {
		out, _, rc = runBinary(t, nil, "--zip", good, "--manifest", good+".manifest.json", "--expected-release", f.ReleaseID, "--public-key", key,
			"--tree-root", tree, "--receipt-dir", dir)
		if rc != 0 || !strings.HasSuffix(out, "RECEIPT: not written (receipt directory is inside the delivery tree; keep receipts outside)\n") {
			t.Errorf("receipt dir %s: rc %d\n%s", dir, rc, out)
		}
		if _, err := os.Stat(filepath.Join(tree, "pail-core", "receipts")); err == nil {
			t.Errorf("receipt directory created inside the tree")
		}
	}
	// A modified tree never changes the exit code; symlinks print as (symlink) and count as extra.
	mod := t.TempDir()
	for _, rel := range []string{"images.lock.json", "run.sh", "native/BUILD.json", "pail-core/README.md", "pail-core/cloud/go.sum"} {
		data, err := os.ReadFile(filepath.Join(tree, filepath.FromSlash(rel)))
		if err != nil {
			t.Fatal(err)
		}
		os.MkdirAll(filepath.Dir(filepath.Join(mod, rel)), 0o755)
		os.WriteFile(filepath.Join(mod, rel), data, 0o644)
	}
	os.Symlink(filepath.Join(mod, "run.sh"), filepath.Join(mod, "pail-core", "link"))
	out, _, rc = runBinary(t, nil, append(base, "--tree-root", mod)...)
	want := "TREE: MODIFIED — 0 changed, 2 missing, 1 extra: pail-core/docs/ßœ.md(missing), pail-core/docs/🤖.md(missing), pail-core/link(symlink)\n"
	if rc != 0 || !strings.HasSuffix(out, want) {
		t.Errorf("modified tree: rc %d\n%s", rc, out)
	}
	// 25 extra files: the totals count the full list, five paths are printed, the receipt keeps the first 20.
	many := t.TempDir()
	for _, rel := range []string{"images.lock.json", "run.sh", "native/BUILD.json", "pail-core/README.md", "pail-core/cloud/go.sum", "pail-core/docs/ßœ.md", "pail-core/docs/🤖.md"} {
		data, err := os.ReadFile(filepath.Join(tree, filepath.FromSlash(rel)))
		if err != nil {
			t.Fatal(err)
		}
		os.MkdirAll(filepath.Dir(filepath.Join(many, rel)), 0o755)
		os.WriteFile(filepath.Join(many, rel), data, 0o644)
	}
	for i := 0; i < 25; i++ {
		os.WriteFile(filepath.Join(many, fmt.Sprintf("extra-%02d.txt", i)), []byte("e"), 0o644)
	}
	manyDir := t.TempDir()
	out, _, rc = runBinary(t, nil, "--zip", good, "--manifest", good+".manifest.json", "--expected-release", f.ReleaseID, "--public-key", key,
		"--tree-root", many, "--receipt-dir", manyDir)
	if rc != 0 || !strings.Contains(out, "\nTREE: MODIFIED — 0 changed, 0 missing, 25 extra: extra-00.txt(extra), extra-01.txt(extra), extra-02.txt(extra), extra-03.txt(extra), extra-04.txt(extra)\n") {
		t.Errorf("25 extra: rc %d\n%s", rc, out)
	}
	entries, _ := os.ReadDir(manyDir)
	if len(entries) != 1 {
		t.Fatalf("receipt dir: %v", entries)
	}
	data, _ := os.ReadFile(filepath.Join(manyDir, entries[0].Name()))
	var r releaseverify.Receipt
	json.Unmarshal(data, &r)
	if r.TreeMatched == nil || *r.TreeMatched || len(r.TreeMismatches) != 20 || r.TreeMismatches[19] != (releaseverify.Mismatch{Path: "extra-19.txt", Kind: "extra"}) {
		t.Errorf("receipt cap: %+v", r)
	}
	// --sig-only and --vector print no tree lines.
	out, _, _ = runBinary(t, nil, "--sig-only", "--manifest", good+".manifest.json", "--public-key", key, "--tree-root", tree)
	if strings.Contains(out, "TREE") || strings.Contains(out, "VERIFIER") {
		t.Errorf("sig-only: %s", out)
	}
}

func TestDefaultKeyFromBundleRoot(t *testing.T) {
	root, f := loadFixture(t)
	good := filepath.Join(root, "good", f.Artifact)
	// a bundle root holds the publisher key under its shipped name; the fixture key is TEST-SIGNING-KEY.pub, so stage it
	broot := t.TempDir()
	pem, err := os.ReadFile(filepath.Join(root, "TEST-SIGNING-KEY.pub"))
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(broot, "RELEASE-SIGNING-KEY.pub"), pem, 0o644); err != nil {
		t.Fatal(err)
	}
	out, _, rc := runBinary(t, nil, "--zip", good, "--manifest", good+".manifest.json", "--expected-release", f.ReleaseID,
		"--bundle-root", broot, "--no-receipt")
	if rc != 0 || !strings.Contains(out, "SIGNATURE: VERIFIED key="+f.TestKeyFingerprint+" with pail_verify\n") {
		t.Errorf("bundle-root key: rc %d\n%s", rc, out)
	}
	// Without --bundle-root the key is looked up in the current directory (absent here) -> rc 2 path -> FAIL.
	cmd := exec.Command(binary, "--zip", good, "--manifest", good+".manifest.json", "--expected-release", f.ReleaseID, "--no-receipt")
	cmd.Dir = t.TempDir()
	outb, _ := cmd.Output()
	if !strings.Contains(string(outb), "SIGNATURE: public key not found; expected RELEASE-SIGNING-KEY.pub beside this tool or --public-key; a signature is required") {
		t.Errorf("default key: %s", outb)
	}
}

func TestSigOnly(t *testing.T) {
	root, f := loadFixture(t)
	manifest := filepath.Join(root, "good", f.Artifact+".manifest.json")
	key := filepath.Join(root, "TEST-SIGNING-KEY.pub")
	out, _, rc := runBinary(t, nil, "--sig-only", "--manifest", manifest, "--public-key", key)
	if rc != 0 || out != "SIGNATURE: VERIFIED key="+f.TestKeyFingerprint+" with pail_verify\n" {
		t.Errorf("sig-only good: %d %q", rc, out)
	}
	out, _, rc = runBinary(t, nil, "--sig-only", "--manifest", manifest, "--public-key", filepath.Join(root, "TEST-WRONG-KEY.pub"))
	if rc != 1 || !strings.HasPrefix(out, "SIGNATURE: BAD SIGNATURE key=") {
		t.Errorf("sig-only wrong key: %d %q", rc, out)
	}
	out, _, rc = runBinary(t, nil, "--sig-only", "--manifest", manifest, "--public-key", key, "--expected-fingerprint", strings.Repeat("0", 64))
	if rc != 1 || !strings.HasPrefix(out, "SIGNATURE: KEY MISMATCH key=") {
		t.Errorf("sig-only fingerprint: %d %q", rc, out)
	}
	out, _, rc = runBinary(t, nil, "--sig-only", "--manifest", filepath.Join(root, "sig-missing", f.Artifact+".manifest.json"), "--public-key", key)
	if rc != 2 || !strings.HasPrefix(out, "SIGNATURE: no signature file beside the manifest (") {
		t.Errorf("sig-only no sig: %d %q", rc, out)
	}
	broot := t.TempDir()
	pem, _ := os.ReadFile(key)
	os.WriteFile(filepath.Join(broot, "RELEASE-SIGNING-KEY.pub"), pem, 0o644)
	out, _, rc = runBinary(t, nil, "--sig-only", "--manifest", manifest, "--bundle-root", broot)
	if rc != 0 || !strings.HasPrefix(out, "SIGNATURE: VERIFIED") {
		t.Errorf("sig-only bundle-root: %d %q", rc, out)
	}
	// A key that is not an Ed25519 SPKI is a verifier fault: rc 2 with the Python message.
	bad := filepath.Join(t.TempDir(), "bad.pub")
	os.WriteFile(bad, []byte("-----BEGIN PUBLIC KEY-----\nAAAA\n-----END PUBLIC KEY-----\n"), 0o644)
	out, _, rc = runBinary(t, nil, "--sig-only", "--manifest", manifest, "--public-key", bad)
	if rc != 2 || out != "SIGNATURE: not an Ed25519 SubjectPublicKeyInfo: "+bad+"\n" {
		t.Errorf("sig-only bad key: %d %q", rc, out)
	}
}

func TestReceipt(t *testing.T) {
	root, f := loadFixture(t)
	good := filepath.Join(root, "good", f.Artifact)
	manifest := good + ".manifest.json"
	key := filepath.Join(root, "TEST-SIGNING-KEY.pub")
	dir := filepath.Join(t.TempDir(), "verification")
	out, _, rc := runBinary(t, nil, "--zip", good, "--manifest", manifest, "--expected-release", f.ReleaseID,
		"--public-key", key, "--expected-fingerprint", f.TestKeyFingerprint, "--receipt-dir", dir)
	if rc != 0 {
		t.Fatalf("rc %d\n%s", rc, out)
	}
	m, err := releaseverify.LoadManifest(manifest)
	if err != nil {
		t.Fatal(err)
	}
	lock := m.FilesSHA256["images.lock.json"]
	want := filepath.Join(dir, f.ReleaseID+"-"+lock[:16]+".json")
	if !strings.HasSuffix(out, "RECEIPT: "+want+"\n") {
		t.Errorf("receipt line:\n%s", out)
	}
	data, err := os.ReadFile(want)
	if err != nil {
		t.Fatal(err)
	}
	var r releaseverify.Receipt
	if err := json.Unmarshal(data, &r); err != nil {
		t.Fatal(err)
	}
	manifestSum, _ := releaseverify.FileSHA256(manifest)
	treeKeys := releaseverify.TreeKeys(m.FilesSHA256)
	if r.SchemaVersion != 2 || r.ReleaseID != f.ReleaseID || r.Artifact != f.Artifact || r.ZipSHA256 != m.SHA256 ||
		r.ManifestSHA256 != manifestSum || r.LockSHA256 != lock || r.Signature != "VERIFIED" ||
		r.KeyFingerprint == nil || *r.KeyFingerprint != f.TestKeyFingerprint || !r.ExpectedFingerprintGiven ||
		r.Backend == nil || *r.Backend != "pail_verify" || r.VerifierNote != "this is the bundled verifier (pail_verify)" ||
		r.Tool != "pail_verify" || r.Files != m.FileCount || r.TreeScope != "manifest files except images/" ||
		r.TreeFiles != len(treeKeys) || r.TreeSHA256 != releaseverify.TreeDigest(treeKeys) || r.TreeMatched != nil ||
		r.TreeMismatches == nil || len(r.TreeMismatches) != 0 || len(r.At) != 20 || !strings.HasSuffix(r.At, "Z") {
		t.Errorf("receipt fields: %+v", r)
	}
	// Not compared (no tree root with a lock): tree_matched is JSON null, the list is empty, the digest is the manifest's.
	if !strings.Contains(string(data), "  \"tree_sha256\": \""+releaseverify.TreeDigest(treeKeys)+"\",\n  \"tree_matched\": null,\n  \"tree_mismatches\": [],\n") {
		t.Errorf("not-compared receipt bytes:\n%s", data)
	}
	if st, _ := os.Stat(dir); st.Mode().Perm() != 0o700 {
		t.Errorf("receipt dir mode %v", st.Mode())
	}
	// Compared and matched: tree_matched true. The same receipt is then protected from a modified-tree run (kept),
	// and written with tree_matched false only once the matched receipt is gone.
	treeDir := filepath.Join(t.TempDir(), "tree")
	out, _, rc = runBinary(t, nil, "--zip", good, "--manifest", manifest, "--expected-release", f.ReleaseID, "--public-key", key,
		"--receipt-dir", treeDir, "--tree-root", filepath.Join(root, "tree-match", "tree"))
	treeWant := filepath.Join(treeDir, f.ReleaseID+"-"+lock[:16]+".json")
	if rc != 0 || !strings.HasSuffix(out, "RECEIPT: "+treeWant+"\n") {
		t.Fatalf("tree receipt: rc %d\n%s", rc, out)
	}
	matched, _ := os.ReadFile(treeWant)
	r = releaseverify.Receipt{}
	json.Unmarshal(matched, &r)
	if r.TreeMatched == nil || !*r.TreeMatched || r.TreeFiles != 7 || len(r.TreeMismatches) != 0 {
		t.Errorf("matched receipt: %+v", r)
	}
	out, _, rc = runBinary(t, nil, "--zip", good, "--manifest", manifest, "--expected-release", f.ReleaseID, "--public-key", key,
		"--receipt-dir", treeDir, "--tree-root", filepath.Join(root, "tree-modified", "tree"))
	if rc != 0 || !strings.HasSuffix(out, "RECEIPT: kept "+treeWant+" (existing receipt matched the tree; this run's tree is modified)\n") {
		t.Errorf("kept: rc %d\n%s", rc, out)
	}
	if after, _ := os.ReadFile(treeWant); string(after) != string(matched) {
		t.Errorf("matched receipt overwritten:\n%s", after)
	}
	// ... and from a run that did not compare the tree at all (null), with its own message.
	out, _, rc = runBinary(t, nil, "--zip", good, "--manifest", manifest, "--expected-release", f.ReleaseID, "--public-key", key,
		"--receipt-dir", treeDir, "--tree-root", filepath.Join(root, "tree-match", "tree"), "--no-tree-check")
	if rc != 0 || !strings.HasSuffix(out, "TREE: skipped (--no-tree-check)\nRECEIPT: kept "+treeWant+" (existing receipt matched the tree; this run did not compare the tree)\n") {
		t.Errorf("kept (null): rc %d\n%s", rc, out)
	}
	if after, _ := os.ReadFile(treeWant); string(after) != string(matched) {
		t.Errorf("matched receipt overwritten by a null run:\n%s", after)
	}
	os.Remove(treeWant)
	out, _, rc = runBinary(t, nil, "--zip", good, "--manifest", manifest, "--expected-release", f.ReleaseID, "--public-key", key,
		"--receipt-dir", treeDir, "--tree-root", filepath.Join(root, "tree-modified", "tree"))
	if rc != 0 || !strings.HasSuffix(out, "RECEIPT: "+treeWant+"\n") {
		t.Errorf("modified receipt: rc %d\n%s", rc, out)
	}
	data, _ = os.ReadFile(treeWant)
	r = releaseverify.Receipt{}
	json.Unmarshal(data, &r)
	if r.TreeMatched == nil || *r.TreeMatched || len(r.TreeMismatches) != 3 || r.TreeMismatches[0] != (releaseverify.Mismatch{Path: "pail-core/README.md", Kind: "changed"}) ||
		r.TreeMismatches[1] != (releaseverify.Mismatch{Path: "pail-core/extra.txt", Kind: "extra"}) || r.TreeMismatches[2] != (releaseverify.Mismatch{Path: "run.sh", Kind: "missing"}) ||
		r.TreeSHA256 != releaseverify.TreeDigest(treeKeys) {
		t.Errorf("modified receipt: %+v", r)
	}
	// A matched run replaces a modified receipt.
	out, _, rc = runBinary(t, nil, "--zip", good, "--manifest", manifest, "--expected-release", f.ReleaseID, "--public-key", key,
		"--receipt-dir", treeDir, "--tree-root", filepath.Join(root, "tree-match", "tree"))
	data, _ = os.ReadFile(treeWant)
	if rc != 0 || !strings.HasSuffix(out, "RECEIPT: "+treeWant+"\n") || !strings.Contains(string(data), "\"tree_matched\": true") {
		t.Errorf("matched over modified: rc %d\n%s\n%s", rc, out, data)
	}
	// CHECKSUMS_ONLY via --allow-unsigned, directory from the environment.
	unsigned := filepath.Join(root, "sig-missing", f.Artifact)
	envDir := filepath.Join(t.TempDir(), "env")
	out, _, rc = runBinary(t, []string{"PAIL_VERIFICATION_RECEIPT_DIR=" + envDir}, "--zip", unsigned, "--manifest", unsigned+".manifest.json",
		"--expected-release", f.ReleaseID, "--public-key", key, "--allow-unsigned")
	if rc != 0 || !strings.Contains(out, "RECEIPT: "+filepath.Join(envDir, f.ReleaseID+"-"+lock[:16]+".json")+"\n") {
		t.Errorf("env receipt: rc %d\n%s", rc, out)
	}
	data, _ = os.ReadFile(filepath.Join(envDir, f.ReleaseID+"-"+lock[:16]+".json"))
	r = releaseverify.Receipt{}
	json.Unmarshal(data, &r)
	if r.Signature != "CHECKSUMS_ONLY" || r.KeyFingerprint != nil || r.Backend != nil || r.ExpectedFingerprintGiven {
		t.Errorf("checksums-only receipt: %+v", r)
	}
	// The keys are present as JSON null, exactly as the Python tool writes them.
	if !strings.Contains(string(data), "\"key_fingerprint\": null,\n") || !strings.Contains(string(data), "\"backend\": null,\n") {
		t.Errorf("checksums-only receipt bytes:\n%s", data)
	}
	// A receipt that cannot be written never changes the verdict.
	blocked := filepath.Join(t.TempDir(), "file")
	os.WriteFile(blocked, []byte("x"), 0o644)
	out, _, rc = runBinary(t, nil, "--zip", good, "--manifest", manifest, "--expected-release", f.ReleaseID,
		"--public-key", key, "--receipt-dir", filepath.Join(blocked, "sub"))
	if rc != 0 || !strings.Contains(out, "RECEIPT: not written (") {
		t.Errorf("unwritable receipt dir: rc %d\n%s", rc, out)
	}
	// No receipt line at all with --no-receipt; a FAIL never writes one.
	out, _, rc = runBinary(t, nil, "--zip", good, "--manifest", manifest, "--expected-release", f.ReleaseID, "--public-key", key, "--no-receipt")
	if rc != 0 || strings.Contains(out, "RECEIPT") {
		t.Errorf("no-receipt: %s", out)
	}
	failDir := filepath.Join(t.TempDir(), "fail")
	_, _, rc = runBinary(t, nil, "--zip", unsigned, "--manifest", unsigned+".manifest.json", "--expected-release", f.ReleaseID,
		"--public-key", key, "--receipt-dir", failDir)
	if _, err := os.Stat(failDir); rc != 1 || err == nil {
		t.Errorf("FAIL wrote a receipt: rc %d err %v", rc, err)
	}
}

func TestVector(t *testing.T) {
	pub, priv, _ := ed25519.GenerateKey(rand.Reader)
	msg := []byte("pail signature vector")
	sig := ed25519.Sign(priv, msg)
	bad := append([]byte{}, sig...)
	bad[63] ^= 0x01
	sum := sha256.Sum256(pub)
	prefix, _ := hex.DecodeString("302a300506032b6570032100")
	der := append(prefix, pub...)
	v := map[string]string{"purpose": "doctor capability check", "fingerprint": hex.EncodeToString(sum[:]),
		"public_key_pem":          "-----BEGIN PUBLIC KEY-----\n" + base64.StdEncoding.EncodeToString(der) + "\n-----END PUBLIC KEY-----\n",
		"message_b64":             base64.StdEncoding.EncodeToString(msg),
		"signature_b64":           base64.StdEncoding.EncodeToString(sig),
		"corrupted_signature_b64": base64.StdEncoding.EncodeToString(bad)}
	p := filepath.Join(t.TempDir(), "vector.json")
	data, _ := json.Marshal(v)
	os.WriteFile(p, data, 0o644)
	out, _, rc := runBinary(t, nil, "--vector", p)
	if rc != 0 || out != "VECTOR: positive=VERIFIED negative=BAD_SIGNATURE backend=pail_verify\n" {
		t.Errorf("vector: %d %q", rc, out)
	}
	// A vector whose "corrupted" signature still verifies must fail (rc 1).
	v["corrupted_signature_b64"] = v["signature_b64"]
	data, _ = json.Marshal(v)
	os.WriteFile(p, data, 0o644)
	out, _, rc = runBinary(t, nil, "--vector", p)
	if rc != 1 || out != "VECTOR: positive=VERIFIED negative=VERIFIED backend=pail_verify\n" {
		t.Errorf("vector negative accepted: %d %q", rc, out)
	}
	out, _, rc = runBinary(t, nil, "--vector", filepath.Join(t.TempDir(), "missing.json"))
	if rc != 2 || !strings.HasPrefix(out, "VECTOR: error ") {
		t.Errorf("vector missing: %d %q", rc, out)
	}
}

func TestUsageErrors(t *testing.T) {
	for _, args := range [][]string{
		{},
		{"--zip", "a.zip"},
		{"--manifest", "m.json"},
		{"--zip", "a.zip", "--manifest", "m.json", "--expected-release", "r", "--receipt-dir", "d", "--no-receipt"},
		{"--bogus"},
		{"--sig-only", "--manifest", "m.json", "extra"},
	} {
		out, errOut, rc := runBinary(t, nil, args...)
		if rc != 2 || out != "" || errOut == "" {
			t.Errorf("%v: rc %d stdout %q stderr %q", args, rc, out, errOut)
		}
	}
}
